          effect: "사랑은 애써 가꿔야 자라는데 미움은 내버려 둬도 자란다는 대비가, '미움을 조심하라'는 말을 한 번도 하지 않고 전달한다. '물을 주지 않아도'라는 조건 하나가 문장 전체의 무게를 만든다.",
