        exampleExplain: "'바람도 없는 공중에' 자리에 '누가 밟은 적도 없는데'를 놓아 원인을 지우고, 긴 수식 끝에 '그림자는'을 두었다가 '누구의 기척입니까'로 닫았다. 따라 쓸 때는 사물 하나를 길게 꾸미고 질문 하나로 끊는다.",
