          effect: "감정을 직접 말하지 않고도 호격과 구체적 풍경만으로 그리움 전체가 독자에게 전달된다. '강변 살자'는 청유형이 소망을 부드럽게 드러내고, '금모래빛'이라는 시각 이미지가 기억을 선명하게 각인시킨다.",
