        goodExample: "우리는 불을 켤 때에 꺼질 것을 아는 것과 같이, 불이 꺼질 때에 다시 켜질 것을 믿는다.",
        exampleExplain: "'만날/떠날' 자리에 '켤/꺼질'을 놓고 앞뒤 절에서 자리를 바꿨다. 새 낱말 없이 순서만 뒤집어 불안이 확신이 되는 구조 — 따라 쓸 때는 서로 반대인 동사 한 쌍만 고르면 된다.",
