        exampleExplain: "'꽃 피네, 꽃이 피네' 자리에 '비 오네, 비가 오네'를 놓아 조사 하나만 더해 변주했다. 똑같이 세 번 반복하면 리듬이 죽으므로 매번 한 글자씩 달라지는 것이 핵심 — 반복할 현상과 지울 시간 경계를 정하면 된다.",
